[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>ScreenVault — UI & UX Design Inspiration</title>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@300;400;500;600;700;800&display=swap" rel="stylesheet" />
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --bg: #ffffff;
      --bg-surface: #f7f7f8;
      --bg-muted: #f0f0f2;
      --text: #141414;
      --text-secondary: #6b7280;
      --text-muted: #9ca3af;
      --border: #e5e7eb;
      --border-light: #f3f4f6;
      --accent: #2563eb;
      --accent-hover: #1d4ed8;
      --accent-light: #eff6ff;
      --accent-subtle: #dbeafe;
      --radius-sm: 8px;
      --radius-md: 12px;
      --radius-lg: 16px;
      --radius-xl: 24px;
      --shadow-sm: 0 1px 3px rgba(0,0,0,0.06), 0 1px 2px rgba(0,0,0,0.04);
      --shadow-md: 0 4px 12px rgba(0,0,0,0.08), 0 2px 4px rgba(0,0,0,0.04);
      --shadow-lg: 0 10px 40px rgba(0,0,0,0.1), 0 4px 12px rgba(0,0,0,0.05);
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: 'Plus Jakarta Sans', sans-serif;
      background: var(--bg);
      color: var(--text);
      font-size: 16px;
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
      overflow-x: hidden;
    }

    /* ── ANNOUNCEMENT BAR ── */
    .announcement-bar {
      background: var(--text);
      color: #fff;
      text-align: center;
      padding: 10px 16px;
      font-size: 13px;
      font-weight: 500;
      letter-spacing: 0.01em;
    }
    .announcement-bar a { color: #93c5fd; text-decoration: none; }
    .announcement-bar a:hover { text-decoration: underline; }

    /* ── NAV ── */
    nav {
      position: sticky;
      top: 0;
      z-index: 100;
      background: rgba(255,255,255,0.92);
      backdrop-filter: blur(16px);
      -webkit-backdrop-filter: blur(16px);
      border-bottom: 1px solid var(--border);
    }
    .nav-inner {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 24px;
      height: 60px;
      display: flex;
      align-items: center;
      justify-content: space-between;
    }
    .nav-logo {
      font-size: 17px;
      font-weight: 700;
      color: var(--text);
      text-decoration: none;
      letter-spacing: -0.02em;
    }
    .nav-logo span { color: var(--accent); }
    .nav-links {
      display: flex;
      align-items: center;
      gap: 6px;
      list-style: none;
    }
    .nav-links a {
      font-size: 14px;
      font-weight: 500;
      color: var(--text-secondary);
      text-decoration: none;
      padding: 6px 12px;
      border-radius: var(--radius-sm);
      transition: color 0.15s, background 0.15s;
    }
    .nav-links a:hover { color: var(--text); background: var(--bg-surface); }
    .nav-cta {
      background: var(--text) !important;
      color: #fff !important;
      border-radius: var(--radius-sm) !important;
      padding: 7px 16px !important;
    }
    .nav-cta:hover { background: #333 !important; }
    .nav-hamburger {
      display: none;
      background: none;
      border: 1px solid var(--border);
      border-radius: var(--radius-sm);
      padding: 6px 10px;
      cursor: pointer;
      font-size: 18px;
      color: var(--text);
    }
    @media (max-width: 768px) {
      .nav-hamburger { display: flex; align-items: center; }
      .nav-links { display: none; }
      .nav-links.open {
        display: flex;
        flex-direction: column;
        position: absolute;
        top: 60px;
        left: 0; right: 0;
        background: #fff;
        border-bottom: 1px solid var(--border);
        padding: 12px 16px;
        gap: 4px;
        align-items: stretch;
      }
      .nav-links.open a { display: block; }
    }

    /* ── SHARED LAYOUT ── */
    .container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }
    .section { padding: 96px 0; }
    .section-sm { padding: 72px 0; }
    .section-label {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      font-size: 12px;
      font-weight: 600;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: var(--accent);
      background: var(--accent-light);
      padding: 5px 12px;
      border-radius: 100px;
      margin-bottom: 20px;
    }
    .section-title {
      font-size: clamp(28px, 4vw, 44px);
      font-weight: 800;
      letter-spacing: -0.03em;
      line-height: 1.15;
      color: var(--text);
    }
    .section-subtitle {
      font-size: 17px;
      color: var(--text-secondary);
      line-height: 1.6;
      max-width: 560px;
      margin-top: 14px;
    }

    /* ── HERO ── */
    .hero {
      padding: 80px 0 72px;
      text-align: center;
      background: linear-gradient(180deg, #fafbff 0%, #ffffff 100%);
      position: relative;
      overflow: hidden;
    }
    .hero::before {
      content: '';
      position: absolute;
      inset: 0;
      background: radial-gradient(ellipse 80% 60% at 50% 0%, rgba(37,99,235,0.06) 0%, transparent 70%);
      pointer-events: none;
    }
    .hero-eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      font-size: 13px;
      font-weight: 600;
      color: var(--text-secondary);
      background: var(--bg-surface);
      border: 1px solid var(--border);
      border-radius: 100px;
      padding: 6px 14px;
      margin-bottom: 28px;
    }
    .hero-eyebrow .dot {
      width: 6px; height: 6px;
      background: #22c55e;
      border-radius: 50%;
      flex-shrink: 0;
    }
    .hero-title {
      font-size: clamp(36px, 5.5vw, 72px);
      font-weight: 800;
      letter-spacing: -0.04em;
      line-height: 1.08;
      color: var(--text);
      max-width: 780px;
      margin: 0 auto 20px;
    }
    .hero-subtitle {
      font-size: clamp(15px, 2vw, 19px);
      color: var(--text-secondary);
      max-width: 540px;
      margin: 0 auto 36px;
      line-height: 1.6;
      font-weight: 400;
    }
    .hero-ctas {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 12px;
      flex-wrap: wrap;
    }
    .btn-primary {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: var(--accent);
      color: #fff;
      font-family: inherit;
      font-size: 15px;
      font-weight: 600;
      padding: 12px 24px;
      border-radius: var(--radius-md);
      border: none;
      cursor: pointer;
      text-decoration: none;
      transition: background 0.15s, transform 0.15s, box-shadow 0.15s;
      box-shadow: 0 2px 8px rgba(37,99,235,0.3);
    }
    .btn-primary:hover {
      background: var(--accent-hover);
      transform: translateY(-1px);
      box-shadow: 0 4px 16px rgba(37,99,235,0.35);
    }
    .btn-secondary {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: transparent;
      color: var(--text);
      font-family: inherit;
      font-size: 15px;
      font-weight: 600;
      padding: 12px 20px;
      border-radius: var(--radius-md);
      border: 1px solid var(--border);
      cursor: pointer;
      text-decoration: none;
      transition: border-color 0.15s, background 0.15s, transform 0.15s;
    }
    .btn-secondary:hover {
      border-color: #d1d5db;
      background: var(--bg-surface);
      transform: translateY(-1px);
    }

    /* Hero screenshot mosaic */
    .hero-visual {
      margin-top: 56px;
      position: relative;
    }
    .screenshot-mosaic {
      display: grid;
      grid-template-columns: repeat(5, 1fr);
      gap: 10px;
      max-width: 960px;
      margin: 0 auto;
      padding: 0 24px;
      -webkit-mask-image: linear-gradient(to bottom, rgba(0,0,0,1) 50%, rgba(0,0,0,0) 100%);
      mask-image: linear-gradient(to bottom, rgba(0,0,0,1) 50%, rgba(0,0,0,0) 100%);
    }
    .mock-screen {
      aspect-ratio: 9/16;
      border-radius: 12px;
      background: var(--bg-surface);
      border: 1px solid var(--border);
      overflow: hidden;
      position: relative;
    }
    .mock-screen:nth-child(3n) { background: #f0f4ff; }
    .mock-screen:nth-child(5n) { background: #fef3f2; }
    .mock-screen:nth-child(7n) { background: #f0fdf4; }
    .mock-screen:nth-child(4n) { background: #fdf4ff; }
    .mock-screen-inner {
      padding: 10px 8px;
      display: flex;
      flex-direction: column;
      gap: 6px;
      height: 100%;
    }
    .mock-bar { height: 6px; border-radius: 3px; background: rgba(0,0,0,0.08); }
    .mock-bar.wide { width: 80%; }
    .mock-bar.medium { width: 55%; }
    .mock-bar.short { width: 35%; }
    .mock-block {
      border-radius: 6px;
      background: rgba(0,0,0,0.06);
      flex-shrink: 0;
    }
    .mock-avatar {
      width: 28px; height: 28px;
      border-radius: 50%;
      background: rgba(0,0,0,0.1);
    }
    .mock-img-placeholder {
      border-radius: 8px;
      background: rgba(0,0,0,0.06);
      flex: 1;
    }
    .mock-cta-btn {
      height: 22px;
      border-radius: 6px;
      background: var(--accent);
      opacity: 0.7;
    }
    @media (max-width: 768px) {
      .screenshot-mosaic { grid-template-columns: repeat(3, 1fr); }
      .screenshot-mosaic .mock-screen:nth-child(n+10) { display: none; }
    }

    /* ── TRUSTED BY ── */
    .trusted-by {
      padding: 48px 0;
      border-top: 1px solid var(--border-light);
      border-bottom: 1px solid var(--border-light);
      text-align: center;
    }
    .trusted-label {
      font-size: 12px;
      font-weight: 600;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: var(--text-muted);
      margin-bottom: 28px;
    }
    .brand-logos {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 40px;
      flex-wrap: wrap;
    }
    .brand-logo-item {
      font-size: 15px;
      font-weight: 700;
      color: var(--text-muted);
      letter-spacing: -0.01em;
      opacity: 0.6;
      transition: opacity 0.2s;
    }
    .brand-logo-item:hover { opacity: 1; }
    @media (max-width: 768px) {
      .brand-logos { gap: 24px; }
      .brand-logo-item { font-size: 13px; }
    }

    /* ── STATS ── */
    .stats-section {
      background: var(--text);
      color: #fff;
      padding: 80px 0;
    }
    .stats-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 0;
